/* 小型主数据维护切片，独立HTML拥有页面结构；业务数据仅会话模拟。 */
(()=>{const page=document.body.dataset.page,isTemplate=page==='equipment-templates';if(page!=='equipment-templates')return;
const s=Eam.s;s.assetMaster ||= {templates:[],locations:[],events:[]};const key=isTemplate?'templates':'locations',rows=s.assetMaster[key],can=Eam.can(['engineer','supervisor']),status={draft:'草稿',pending:'待审核',published:'已发布',stopped:'停用'};let current=null,pageIndex=1;
const get=id=>document.getElementById('master-'+id),value=id=>get(id)?.value.trim()||'';
function guard(){if(['failure','conflict'].includes(s.scenario)){Eam.message(s.scenario==='failure'?'提交失败，草稿保持不变':'版本冲突，请刷新后重试');return false;}return true;}
function log(command,before,after,reason){s.assetMaster.events.push({id:crypto.randomUUID(),page,command,before:before?structuredClone(before):null,after:after?structuredClone(after):null,reason,actor:s.person,at:new Date().toISOString()});Eam.save();}
function options(){if(isTemplate)return;get('parent').replaceChildren(new Option('根位置',''));for(const row of rows.filter(x=>x.id!==current?.id&&x.status==='published'))get('parent').add(new Option(row.name,row.id));get('class').replaceChildren(new Option('选择已发布分类',''));for(const row of s.assetMaster.templates.filter(x=>x.status==='published'))get('class').add(new Option(row.name+' / '+row.code,row.id));}
const fields=isTemplate?['code','name','param','param-name','type','unit','min','max','stage']:['code','name','parent','site','tag','slot','class','capacity'];
function open(row,readonly=false){current=row;get('form').reset();options();for(const f of fields)if(row)get(f).value=row[f]??'';get('reason').value='';get('form').querySelectorAll('input,select').forEach(x=>x.disabled=readonly);get('save').hidden=readonly;get('error').textContent='';get('title').textContent=(readonly?'查看':'维护')+' · '+(row?.name||'新草稿');get('dialog').showModal();}
function render(){get('list').replaceChildren();const filtered=rows.filter(x=>(x.code+x.name).toLowerCase().includes(value('search').toLowerCase())&&(!value('status')||x.status===value('status')));get('empty').hidden=!!filtered.length;const pages=Math.max(1,Math.ceil(filtered.length/8));pageIndex=Math.min(pageIndex,pages);for(const row of filtered.slice((pageIndex-1)*8,pageIndex*8)){const tr=document.createElement('tr');for(const [label,text]of [[isTemplate?'分类 / 参数':'位置 / 槽位',row.code+' · '+row.name],["配置",isTemplate?row['param-name']+' / '+row.type+' / '+(row.unit||'无单位'):row.site+' / '+row.slot+' / 容量'+row.capacity],['版本 / 状态','V'+row.revision+' · '+status[row.status]]]){const td=document.createElement('td');td.dataset.label=label;td.textContent=text;tr.append(td);}const td=document.createElement('td');td.dataset.label='操作';const button=(text,fn,enabled=true)=>{const b=document.createElement('button');b.textContent=text;b.disabled=!enabled;b.onclick=fn;td.append(b);};button('查看',()=>open(row,true));if(row.status==='draft'){button('编辑',()=>open(row),can);button('提交审核',()=>change(row,'pending'),can);button('删除草稿',()=>Eam.confirm('删除草稿',reason=>{if(!can||!guard())return false;const referenced=!isTemplate&&rows.some(x=>x.parent===row.id);if(referenced){Eam.message('存在子位置，不可删除');return false;}rows.splice(rows.indexOf(row),1);log('delete',row,null,reason);render();return true;}),can);}if(row.status==='pending'){button('审核发布',()=>change(row,'published'),can&&s.person!==row.author);button('退回',()=>change(row,'draft'),can&&s.person!==row.author);}if(row.status==='published')button('停用',()=>change(row,'stopped'),can);tr.append(td);get('list').append(tr);}EamUiComponents.pagination(get('pagination'),{page:pageIndex,pages,total:filtered.length,pageSize:8,onChange:page=>{pageIndex=page;render();}});EamUiComponents.syncTableState(get('list').closest('table'));}
function change(row,next){Eam.confirm(status[next],reason=>{if(!can||!guard())return false;if(row.status==='pending'&&s.person===row.author){Eam.message('申请人不能审核自己的版本');return false;}if(next==='published'&&!isTemplate&&(!s.assetMaster.templates.some(x=>x.id===row.class&&x.status==='published')||(row.parent&&!rows.some(x=>x.id===row.parent&&x.status==='published')))){Eam.message('分类或父位置已失效，先退回修订');return false;}if(next==='stopped'&&!isTemplate&&rows.some(x=>x.parent===row.id&&x.status!=='stopped')){Eam.message('先处理子位置');return false;}const before=structuredClone(row);row.status=next;row.revision++;log('status',before,row,reason);render();return true;});}
get('form').onsubmit=e=>{e.preventDefault();if(!guard())return;if(!can||current&&current.status!=='draft'){get('error').textContent='无维护权限或当前版本不可编辑';return;}const payload=Object.fromEntries(fields.map(f=>[f,value(f)]));const fail=message=>get('error').textContent=message;if(rows.some(x=>x.id!==current?.id&&x.code.toLowerCase()===payload.code.toLowerCase()))return fail('编码已存在');if(isTemplate&&payload.type==='number'&&payload.min!==''&&payload.max!==''&&Number(payload.min)>Number(payload.max))return fail('下限不能大于上限');if(!isTemplate&&!s.assetMaster.templates.some(x=>x.id===payload.class&&x.status==='published'))return fail('请先维护并独立审核发布设备分类');if(!isTemplate&&payload.tag&&rows.some(x=>x.id!==current?.id&&x.site===payload.site&&x.tag===payload.tag))return fail('同厂区位号已存在');if(!isTemplate){let cursor=payload.parent;const seen=new Set([current?.id]);while(cursor){if(seen.has(cursor))return fail('父位置关系形成循环');seen.add(cursor);cursor=rows.find(x=>x.id===cursor)?.parent;}}const before=current?structuredClone(current):null;const row={...payload,id:current?.id||crypto.randomUUID(),status:'draft',revision:(current?.revision||0)+1,author:s.person};if(current)rows.splice(rows.indexOf(current),1,row);else rows.push(row);log('save',before,row,value('reason'));get('dialog').close();render();};get('new').disabled=!can;get('new').onclick=()=>open(null);get('close').onclick=()=>get('dialog').close();get('search').oninput=()=>{pageIndex=1;render();};get('status').onchange=()=>{pageIndex=1;render();};render();})();
